#include <cassert>
#include <iostream>
#include "services/lock_policy.h"
int main(){assert(!device::autoLockDue(59999,0,false));assert(device::autoLockDue(60000,0,false));assert(!device::autoLockDue(90000,40000,false));assert(!device::autoLockDue(90000,0,true));assert(device::autoLockDue(uint32_t(0xfffffff0u+60000u),0xfffffff0u,false));device::LockKey k;assert(k.press(100));assert(!k.tick(1100,false));assert(k.release(1100,false));assert(!k.press(1110));assert(k.press(1200));assert(!k.tick(3199,false));assert(k.progress>0);assert(k.tick(3200,false));assert(!k.tick(8000,true));assert(!k.release(8100,true));assert(k.press(8200));assert(!k.tick(10199,true));assert(!k.release(10199,true));assert(k.press(10300));assert(!k.tick(12300,true));assert(!k.release(12400,true));device::LockKey delayed;assert(delayed.press(15000));assert(delayed.tick(18000,false));assert(!delayed.release(18000,true));device::LockKey wrap;assert(wrap.press(0xfffffff0));assert(wrap.tick(3000,false));std::cout<<"PASS: short press, debounce, cancellation, manual lock threshold / no held-key unlock, held-key latch and rollover\n";}
